CREATE POLICY "Reception own housekeeping room comments" ON public.room_messages FOR ALL TO authenticated USING (private.is_approved(auth.uid()) AND private.can_access_hotel(hotel_id) AND private.has_role(auth.uid(), 'reception'::public.app_role) AND user_id = auth.uid() AND group_key = 'housekeeping' AND room_number IS NOT NULL) WITH CHECK (private.is_approved(auth.uid()) AND private.can_access_hotel(hotel_id) AND private.has_role(auth.uid(), 'reception'::public.app_role) AND user_id = auth.uid() AND group_key = 'housekeeping' AND room_number IS NOT NULL AND EXISTS (SELECT 1 FROM public.rooms r WHERE r.hotel_id = room_messages.hotel_id AND r.room_number = room_messages.room_number));